<?php
namespace App\Services;
use App\Models\CentralFinanceReceivable; use App\Models\CentralFinanceReceivableAdjustment; use App\Models\CentralFinanceUser; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use InvalidArgumentException;
final class CentralFinanceReceivableAdjustmentService { public function __construct(private readonly CentralFinanceSchoolScopeService $schools,private readonly CentralFinanceDocumentAuditService $audits){} public function adjust(CentralFinanceUser $actor,int $receivableId,string $type,float $delta,string $reason,CarbonImmutable $at,string $key):CentralFinanceReceivableAdjustment { if(!in_array($type,['adjustment','discount','waiver','void'],true)||!is_finite($delta)||trim($reason)===''||!preg_match('/^[A-Za-z0-9_.:-]{2,100}$/',$key))throw new InvalidArgumentException('Central receivable adjustment input is invalid.');return DB::connection('mysql')->transaction(function()use($actor,$receivableId,$type,$delta,$reason,$at,$key){$r=CentralFinanceReceivable::on('mysql')->lockForUpdate()->findOrFail($receivableId);$this->schools->assertCanOperate($actor,$r->school_id);app(CentralFinanceSchoolCutoverService::class)->assertCentralWritesAllowed($r->school_id);if($type==='void'&&$r->amount_paid>0)throw new InvalidArgumentException('A paid receivable requires payment reversal before it can be voided.');$delta=$type==='void' ? -(float)$r->amount_due : $delta;if(($type==='discount'||$type==='waiver')&&$delta>=0)throw new InvalidArgumentException('Discount and waiver must reduce the receivable.');$id=hash('sha256',$r->school_id.'|'.$r->id.'|'.$key);if($existing=CentralFinanceReceivableAdjustment::on('mysql')->where('idempotency_key',$id)->first())return $existing;$new=(float)$r->amount_due+$delta;if($new<0||$new+0.00001<(float)$r->amount_paid)throw new InvalidArgumentException('The adjusted receivable cannot be below collected payments.');$adj=CentralFinanceReceivableAdjustment::on('mysql')->create(['adjustment_uuid'=>(string)Str::uuid(),'school_id'=>$r->school_id,'receivable_id'=>$r->id,'adjustment_type'=>$type,'amount_delta'=>$delta,'idempotency_key'=>$id,'reason'=>trim($reason),'adjusted_at'=>$at,'adjusted_by'=>$actor->id]);$status=$type==='void'?CentralFinanceReceivable::CANCELLED:($new<=(float)$r->amount_paid?($type==='waiver'?CentralFinanceReceivable::WAIVED:CentralFinanceReceivable::PAID):((float)$r->amount_paid>0?CentralFinanceReceivable::PARTIAL:CentralFinanceReceivable::OPEN));$r->update(['amount_due'=>$new,'finance_adjustment_amount'=>(float)$r->finance_adjustment_amount+$delta,'status'=>$status]);$this->audits->record($actor,$adj,'central_receivable_adjustment',$type,trim($reason),['amount_due'=>(float)$r->amount_due-$delta],['receivable_id'=>$r->id,'amount_due'=>$new]);return $adj;});} }
